using EventLensAI.Domain.Entities;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace EventLensAI.Infrastructure.Persistence.Configurations;
internal sealed class BoothExperienceConfigurationMap:IEntityTypeConfiguration<BoothExperienceConfiguration>{public void Configure(EntityTypeBuilder<BoothExperienceConfiguration>b){b.ToTable("BoothExperienceConfigurations");b.HasKey(x=>x.Id);b.Property(x=>x.WelcomeMessage).HasMaxLength(300);b.Property(x=>x.Theme).HasMaxLength(30);b.Property(x=>x.Language).HasMaxLength(10);b.Property(x=>x.BackgroundMedia).HasMaxLength(500);b.HasIndex(x=>x.EventId).IsUnique();b.HasIndex(x=>x.OrganizationId);b.HasQueryFilter(x=>!x.IsDeleted);}}
internal sealed class GuestBoothSessionMap:IEntityTypeConfiguration<GuestBoothSession>{public void Configure(EntityTypeBuilder<GuestBoothSession>b){b.ToTable("GuestBoothSessions");b.HasKey(x=>x.Id);b.Property(x=>x.RecoveryToken).HasMaxLength(64);b.HasIndex(x=>x.EventId);b.HasIndex(x=>new{x.OrganizationId,x.CreatedAt});b.HasIndex(x=>x.RecoveryToken).IsUnique();b.HasQueryFilter(x=>!x.IsDeleted);}}
internal sealed class BoothExperienceLogMap:IEntityTypeConfiguration<BoothExperienceLog>{public void Configure(EntityTypeBuilder<BoothExperienceLog>b){b.ToTable("BoothExperienceLogs");b.HasKey(x=>x.Id);b.Property(x=>x.Reason).HasMaxLength(200);b.HasIndex(x=>x.EventId);b.HasIndex(x=>new{x.OrganizationId,x.CreatedAt});b.HasIndex(x=>new{x.GuestBoothSessionId,x.OccurredAt});b.HasQueryFilter(x=>!x.IsDeleted);}}
